(()=>{"use strict";const html=document.documentElement,menuButton=document.getElementById("menu-button"),menu=document.getElementById("mobile-menu"),themeButton=document.getElementById("theme-button"),savedTheme=localStorage.getItem("theme");(savedTheme==="light"||savedTheme==="dark")&&(html.dataset.theme=savedTheme);function syncThemeLabel(){const dark=html.dataset.theme!=="light";themeButton.textContent=dark?"☼":"☾",themeButton.setAttribute("aria-label",dark?"Chuyển giao diện sáng":"Chuyển giao diện tối")}syncThemeLabel(),themeButton.addEventListener("click",()=>{html.dataset.theme=html.dataset.theme==="light"?"dark":"light",localStorage.setItem("theme",html.dataset.theme),syncThemeLabel()});function closeMenu(){menu.hidden=!0,menuButton.setAttribute("aria-expanded","false"),document.body.style.overflow=""}menuButton.addEventListener("click",()=>{const open=menu.hidden;menu.hidden=!open,menuButton.setAttribute("aria-expanded",String(open)),document.body.style.overflow=open?"hidden":""}),menu.querySelectorAll("a").forEach(link=>link.addEventListener("click",closeMenu)),addEventListener("resize",()=>{innerWidth>=1024&&closeMenu()},{passive:!0}),addEventListener("scroll",()=>document.getElementById("site-header").classList.toggle("scrolled",scrollY>12),{passive:!0});const number=new Intl.NumberFormat("vi-VN");async function loadSummary(){try{const response=await fetch("/api/public/dashboard-summary",{signal:AbortSignal.timeout(1e4)});if(!response.ok)throw new Error;const data=await response.json();for(const key of["total","online","offline","stale"])document.getElementById(`stations-${key}`).textContent=number.format(data.stations[key]||0);document.getElementById("summary-updated").textContent=`Cập nhật ${new Intl.DateTimeFormat("vi-VN",{dateStyle:"short",timeStyle:"short"}).format(new Date(data.updated_at))}`}catch{document.getElementById("summary-updated").textContent="Chưa thể cập nhật dữ liệu"}}loadSummary()})();
